import java.util.*;
public class Main {
 static int prec(char c){return c=='^'?3:(c=='*'||c=='/')?2:(c=='+'||c=='-')?1:0;}
 static String postfix(String in){StringBuilder out=new StringBuilder();Deque<Character> st=new ArrayDeque<>();for(char c:in.replaceAll("\\s+","").toCharArray()){if(Character.isLetterOrDigit(c))out.append(c);else if(c=='(')st.push(c);else if(c==')'){while(!st.isEmpty()&&st.peek()!='(')out.append(st.pop());if(st.isEmpty())throw new IllegalArgumentException("Mismatched parentheses");st.pop();}else{while(!st.isEmpty()&&st.peek()!='('&&prec(st.peek())>=prec(c))out.append(st.pop());st.push(c);}}while(!st.isEmpty()){char c=st.pop();if(c=='(')throw new IllegalArgumentException("Mismatched parentheses");out.append(c);}return out.toString();}
 static int eval(String p){Deque<Integer>s=new ArrayDeque<>();for(char c:p.toCharArray()){if(Character.isDigit(c))s.push(c-'0');else{if(s.size()<2)throw new IllegalArgumentException("Bad expression");int b=s.pop(),a=s.pop();s.push(switch(c){case '+'->a+b;case '-'->a-b;case '*'->a*b;case '/'->{if(b==0)throw new ArithmeticException("Divide by zero");yield a/b;}case '^'->(int)Math.pow(a,b);default->throw new IllegalArgumentException();});}}if(s.size()!=1)throw new IllegalArgumentException("Bad expression");return s.pop();}
 public static void main(String[]x){Scanner s=new Scanner(System.in);System.out.print("Infix expression (single digit/letter operands): ");String e=s.nextLine();try{String p=postfix(e);System.out.println("Postfix: "+p);if(p.matches("[0-9+*/^()-]+"))System.out.println("Value: "+eval(p));}catch(Exception ex){System.out.println("Error: "+ex.getMessage());}}
}
